import React, { useEffect, useMemo, useRef, useState } from 'react';
import { createRoot } from 'react-dom/client';
import { Activity, ArrowDownRight, ArrowRight, ArrowUpRight, BookOpen, CalendarDays, Check, ChevronDown, ChevronLeft, ChevronRight, Clock3, DoorOpen, GraduationCap, LayoutDashboard, LogOut, Menu, Plus, Search, Settings2, ShieldCheck, Users, X, ChartNoAxesCombined, Eye, EyeOff } from 'lucide-react';
import './styles.css';
import { formatTime, readTimePreference, timePreferenceKey } from './time-format.js';
import { ACADEMIC_ADD_LABELS, ACADEMIC_SEMESTERS, COURSE_DEPARTMENTS, INSTRUCTOR_DEPARTMENTS, SECTION_NAMES, SECTION_PROGRAMS, formatSectionDisplayName, positiveWholeNumber } from '../../shared/academic-options.js';
import { ROOM_FLOORS } from '../../shared/room-options.js';
import { ROLE, ROLE_VALUES, canAccessPage, canRead, isManager as hasManagerRole } from '../../shared/permissions.js';

const API = import.meta.env.VITE_API_URL || '/api';
const nav = [{ id: 'dashboard', label: 'Overview', icon: LayoutDashboard }, { id: 'schedules', label: 'Timetable', icon: CalendarDays }, { id: 'rooms', label: 'Rooms & labs', icon: DoorOpen }, { id: 'requests', label: 'Reservations', icon: Clock3 }, { id: 'courses', label: 'Academic records', icon: GraduationCap }, { id: 'reports', label: 'Reports', icon: ChartNoAxesCombined }];
const roleOptions = ROLE_VALUES;
const roleLabel = role => role === ROLE.ADMIN ? 'Administrator' : role === ROLE.SCHEDULER ? 'Scheduler' : role === ROLE.INSTRUCTOR ? 'Teacher / Instructor' : 'Student';
const titles = { dashboard: 'Good morning', schedules: 'Weekly timetable', rooms: 'Rooms & laboratories', requests: 'Reservation requests', courses: 'Academic records', reports: 'Room utilization reports' };
const formatRoomLocation = room => room ? [room.name || room.code || 'Room', room.floor || 'Floor not assigned', room.building || 'Building not assigned'].join(' · ') : 'Room not assigned';
const todayName = new Intl.DateTimeFormat('en-US', { weekday: 'long', timeZone: 'Asia/Manila' }).format(new Date());
const todayLabel = new Intl.DateTimeFormat('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric', timeZone: 'Asia/Manila' }).format(new Date());
function App() {
  const [identity, setIdentity] = useState(() => JSON.parse(localStorage.getItem('campusIdentity') || 'null'));
  const [logoutPrompt, setLogoutPrompt] = useState(false);
  const [timeFormat, setTimeFormat] = useState(() => readTimePreference(JSON.parse(localStorage.getItem('campusIdentity') || 'null')));
  const [page, setPage] = useState('dashboard'); const [academicTab, setAcademicTab] = useState('courses'); const [data, setData] = useState({}); const [loading, setLoading] = useState(false); const [saving, setSaving] = useState(false); const [error, setError] = useState(''); const [notice, setNotice] = useState(''); const [modal, setModal] = useState(null); const [search, setSearch] = useState(''); const [mobileNav, setMobileNav] = useState(false); const [filters, setFilters] = useState({ room: 'all', instructor: '', section: '', course: '', term: '', day: '', status: '', search: '' }); const refreshSequence = useRef(0);
  const isManager = identity && hasManagerRole(identity.role); const selectedAcademicTab = identity?.role !== ROLE.ADMIN && academicTab === 'users' ? 'courses' : academicTab;
  const activeTerm = data.terms?.find(term => term.status === 'Active');
  const headers = { 'Content-Type': 'application/json', ...(identity ? { Authorization: `Bearer ${identity.token}` } : {}) };
  async function api(path, options = {}) { const response = await fetch(`${API}${path}`, { ...options, headers: { ...headers, ...options.headers } }); const body = await response.json().catch(() => ({})); if (!response.ok) throw Object.assign(new Error(body.message || 'Something went wrong.'), { body }); return body; }
  async function refresh() { if (!identity) return; const sequence = ++refreshSequence.current; setLoading(true); setError(''); try { const sessionUser = await api('/me'); const refreshedIdentity = { ...identity, ...sessionUser, token: identity.token }; const identityChanged = ['name','username','email','role','status','setupRequired','instructor','section'].some(key => String(identity[key] || '') !== String(refreshedIdentity[key] || '')); if (identityChanged) { localStorage.setItem('campusIdentity', JSON.stringify(refreshedIdentity)); setIdentity(refreshedIdentity); if (!canAccessPage(refreshedIdentity.role, page)) setPage('dashboard'); } const role = refreshedIdentity.role; const keys = ['dashboard','rooms','resources','instructors','courses','sections','terms','requests','users'].filter(key => canRead(role, key)); const params = new URLSearchParams(Object.entries(filters).filter(([key,value]) => value && !(key === 'room' && value === 'all')).map(([key,value]) => [key,value])); const requests = [...keys.map(async key => [key, await api(`/${key}`)])]; if (role !== ROLE.STUDENT || refreshedIdentity.section) requests.push(api(`/schedules?${params}`).then(value => ['schedules', value])); const results = await Promise.all(requests); if (sequence === refreshSequence.current) setData(Object.fromEntries(results)); } catch (err) { if (sequence === refreshSequence.current) setError(err.message || 'Could not connect to the scheduling server. Start MongoDB and the API, then try again.'); } finally { if (sequence === refreshSequence.current) setLoading(false); } }  useEffect(() => { refresh(); }, [identity, filters]);
  useEffect(() => { if (!data.rooms?.length && !activeTerm) return; setFilters(current => { const room = current.room || 'all'; const term = current.term || activeTerm?._id || ''; if (room === current.room && term === current.term) return current; return { ...current, room, term }; }); }, [data.rooms, activeTerm]);
  useEffect(() => { if (identity) setTimeFormat(readTimePreference(identity)); }, [identity?._id, identity?.email]);
  useEffect(() => { if (identity && (!canAccessPage(identity.role, page) || identity.role === ROLE.STUDENT && page === 'schedules' && !identity.section)) { setPage('dashboard'); setError(identity.role === ROLE.STUDENT && !identity.section ? 'Access denied. Ask an administrator to assign your student account to a section.' : 'Access denied. This page is not available for your account role.'); } }, [identity?.role, identity?.section, page]);
  function changeTimeFormat(value) { setTimeFormat(value); const key = timePreferenceKey(identity); if (key) { try { localStorage.setItem(key, value); } catch {} } }
  function signOut() { localStorage.removeItem('campusIdentity'); setIdentity(null); setData({}); setLogoutPrompt(false); }
  async function save(path, payload, id) { setSaving(true); setModal(current => current ? {...current,error:''} : current); try { await api(`/${path}${id ? `/${id}` : ''}`, { method: id ? 'PATCH' : 'POST', body: JSON.stringify(payload) }); setModal(null); setNotice(id ? 'Changes saved.' : 'New record added.'); await refresh(); setTimeout(() => setNotice(''), 3200); } catch (err) { const details = err.body?.conflicts?.map(c => `${c.assignment}: ${c.message}`).join(' ') || ''; const message = `${err.message}${details ? ` ${details}` : ''}`; setError(message); setModal(current => current ? {...current,error:message} : current); } finally { setSaving(false); } }  async function deleteRecord(path, record, deactivateInstead = false) { const label = path === 'schedules' ? `${record.course?.code || 'Schedule'} · ${record.day} ${record.startTime}–${record.endTime}` : record.name || record.title || record.code || record.email || 'this record'; setSaving(true); try { const endpoint = deactivateInstead ? `/${path}/${record._id}/deactivate` : `/${path}/${record._id}`; await api(endpoint, { method: deactivateInstead ? 'POST' : 'DELETE' }); setModal(null); setNotice(deactivateInstead ? `${label} deactivated. Access and history are retained.` : path === 'schedules' ? `${label} cancelled and removed from the timetable. History is retained.` : `${label} permanently deleted.`); await refresh(); setTimeout(() => setNotice(''), 3200); } finally { setSaving(false); } }  async function changeStatus(path, record, action) { const label = path === 'schedules' ? `${record.course?.code || 'Schedule'} · ${record.day} ${record.startTime}–${record.endTime}` : record.name || record.title || record.code || record.email || 'Record'; setSaving(true); try { await api(`/${path}/${record._id}/${action}`, { method: 'POST' }); setModal(null); setNotice(`${label} ${action === 'activate' ? 'activated' : 'deactivated'}.`); await refresh(); setTimeout(() => setNotice(''), 3200); } finally { setSaving(false); } }
  async function cancelRequest(request) { try { await api(`/requests/${request._id}/cancel`, { method: 'POST' }); setNotice('Reservation request cancelled.'); await refresh(); } catch (err) { setError(err.message); } }
  async function decide(request, status) { const decisionNotes = window.prompt(`${status === 'Approved' ? 'Optional note for the instructor' : 'Reason for declining'}`, '') ?? null; if (decisionNotes === null) return; const publishToStudents = status === 'Approved' && request.course && request.section && window.confirm('Publish this dated event to the student timetable?'); try { await api(`/requests/${request._id}`, { method: 'PATCH', body: JSON.stringify({ status, decisionNotes, publishToStudents }) }); setNotice(`Request ${status.toLowerCase()}.`); await refresh(); } catch (err) { const detail = err.body?.conflicts?.map(c => `${c.assignment}: ${c.message}`).join(' ') || ''; setError(`${err.message}${detail ? ` ${detail}` : ''}`); } }
  async function signIn(identifier, password) { try { const result = await api('/auth/login', { method: 'POST', body: JSON.stringify({ identifier, password }) }); const value = { ...result.user, token: result.token }; localStorage.setItem('campusIdentity', JSON.stringify(value)); setIdentity(value); setError(''); } catch (err) { setError(err.message); } }
  if (!identity) return <SignIn onSignIn={signIn} error={error} />;
  const accountName = String(identity.name || identity.username || identity.email || 'User').trim();
  const accountInitials = accountName.split(/\s+/).map(part => part[0]).join('').slice(0, 2).toUpperCase();
  const accountFirstName = accountName.split(/\s+/)[0] || 'User';
  const me = identity.role === ROLE.INSTRUCTOR ? identity.instructor : null;
  const mine = (data.schedules || []).filter(s => !me || s.instructor?._id === me);
  const requests = (data.requests || []).filter(r => identity.role !== ROLE.INSTRUCTOR || String(r.requesterUser || '') === String(identity._id) || Boolean(identity.instructor && String(r.requesterInstructor || '') === String(identity.instructor)));
  const filteredSchedules = mine;
  return <div className="app-shell"><aside className={`sidebar ${mobileNav ? 'mobile-open' : ''}`}><div className="brand"><span className="brand-logo-frame"><img className="brand-logo" src="/branding/aclc-college-ormoc-logo.jpg" alt=""/></span><div className="brand-copy"><strong>ACLC College</strong><small>ORMOC CITY, INC. · ROOM SCHEDULER</small></div><button className="icon-btn mobile-close" onClick={() => setMobileNav(false)} aria-label="Close navigation"><X size={18}/></button></div><div className="campus-select"><span className="campus-monogram">O</span><span><strong>Ormoc City Campus</strong><small>{activeTerm ? `${activeTerm.name} · ${activeTerm.schoolYear}` : 'No active term'}</small></span><ChevronDown size={15}/></div><div className="nav-label">WORKSPACE</div><nav>{nav.filter(item => canAccessPage(identity.role, item.id)).map(item => { const Icon = item.icon; return <button key={item.id} onClick={() => { setPage(item.id); setMobileNav(false); setError(''); }} className={`nav-item ${page === item.id ? 'active' : ''}`}><Icon size={18}/><span>{identity.role === ROLE.INSTRUCTOR && item.id === 'schedules' ? 'My timetable' : identity.role === ROLE.STUDENT && item.id === 'schedules' ? 'Published timetable' : identity.role === ROLE.INSTRUCTOR && item.id === 'requests' ? 'My reservations' : item.label}</span>{item.id === 'requests' && data.dashboard?.pending > 0 && <b className="nav-count">{data.dashboard.pending}</b>}</button>; })}</nav><div className="sidebar-bottom"><div className="help-card"><div className="help-icon"><ShieldCheck size={17}/></div><strong>Need a hand?</strong><p>Your scheduling team is here to help.</p><button onClick={() => setNotice('Contact your school scheduling office')}>Contact support <ArrowRight size={14}/></button></div><div className="user-card"><div className="avatar">{accountInitials}</div><span className="user-meta"><strong>{accountName}</strong><small>{roleLabel(identity.role)}</small></span><button className="icon-btn" aria-label="Sign out" title="Sign out" onClick={() => setLogoutPrompt(true)}><LogOut size={17}/></button></div></div></aside>{mobileNav && <button className="nav-scrim" aria-label="Close menu" onClick={() => setMobileNav(false)}/>}
  <main className="main"><header className="topbar"><button className="icon-btn mobile-menu" aria-label="Open navigation" onClick={() => setMobileNav(true)}><Menu size={21}/></button><div className="breadcrumb">ACLC College <span>/</span> <strong>{nav.find(n => n.id === page)?.label}</strong></div><div className="top-actions"><div className="top-avatar">{accountInitials}</div></div></header><div className="page-wrap"><div className="page-head"><div><div className="eyebrow">{page === 'dashboard' ? todayLabel.toUpperCase() : 'ACLC COLLEGE OF ORMOC CITY, INC.'}</div><h1>{page === 'dashboard' ? `${titles[page]}, ${accountFirstName}` : titles[page]}</h1><p className="subhead">{page === 'dashboard' ? 'Here’s what’s happening across your campus today.' : page === 'schedules' ? 'A clear view of what’s happening in every space.' : page === 'rooms' ? 'Explore spaces, capacity and available resources.' : page === 'requests' ? 'Review room requests and track their progress.' : 'Manage courses, instructors and student sections.'}</p></div><div className="head-actions">{isManager && (page === 'rooms' || page === 'courses' || page === 'schedules') && <button className="btn btn-primary" disabled={page === 'schedules' && !(filters.room === 'all' ? data.rooms?.some(room => room.status === 'Active') : data.rooms?.some(room => room._id === filters.room && room.status === 'Active'))} onClick={() => setModal(page === 'schedules' ? { kind: 'schedule', room: filters.room === 'all' ? '' : filters.room } : page === 'rooms' ? { kind: 'room' } : selectedAcademicTab === 'users' ? { kind: 'user' } : { kind: 'academic', type: selectedAcademicTab })}><Plus size={17}/> {page === 'schedules' ? 'Add schedule' : page === 'rooms' ? 'Add a room' : ACADEMIC_ADD_LABELS[selectedAcademicTab]}</button>}{page === 'requests' && identity.role === 'Instructor' && <button className="btn btn-primary" onClick={() => setModal({ kind: 'request' })}><Plus size={17}/> Request a room</button>}</div></div>
  {error && <div className="alert alert-error" role="alert"><span>{error}</span><button className="icon-btn" aria-label="Dismiss" onClick={() => setError('')}><X size={16}/></button></div>}{notice && <div className="alert alert-success" role="status"><Check size={17}/>{notice}<button className="icon-btn" aria-label="Dismiss" onClick={() => setNotice('')}><X size={16}/></button></div>}
  {loading && !Object.keys(data).length ? <div className="loading"><span className="spinner"/> Loading your campus workspace…</div> : !Object.keys(data).length ? <div className="empty-state"><DoorOpen size={28}/><h3>Connect to your scheduling workspace</h3><p>{error || 'Start the API and database to load campus records.'}</p><button className="btn btn-outline" onClick={refresh}>Try again</button></div> : <>
  {page === 'dashboard' && <Dashboard data={data} setPage={setPage} setModal={setModal} isManager={isManager} me={me} timeFormat={timeFormat} />}
  {page === 'rooms' && <Rooms rooms={data.rooms || []} search={search} setSearch={setSearch} isManager={isManager} onEdit={record => setModal({ kind: 'room', record })} onDelete={(type,record) => setModal({kind:'delete',type,record})} onStatusChange={(type,record,action) => setModal({kind:'status',type,record,action})} />}
  {page === 'courses' && <Academic data={data} tab={selectedAcademicTab} onTabChange={setAcademicTab} isManager={isManager} isAdmin={identity.role === ROLE.ADMIN} busy={saving} onEdit={(kind,record) => setModal(kind === 'users' ? { kind: 'user', record } : { kind: 'academic', type: kind, record })} onView={(kind,record) => setModal({ kind: 'academic-view', type: kind, record })} onDelete={(kind,record) => setModal({ kind: 'delete', type: kind, record })} onStatusChange={(kind,record,action) => setModal({ kind: 'status', type: kind, record, action })} />}
  {page === 'schedules' && <Timetable data={data} schedules={filteredSchedules} filters={filters} setFilters={setFilters} isManager={isManager} loading={loading} onEdit={record => setModal({ kind: 'schedule', record })} onDelete={record => setModal({kind:'delete',type:'schedules',record})} onStatusChange={(record,action) => setModal({kind:'status',type:'schedules',record,action})} timeFormat={timeFormat} onTimeFormatChange={changeTimeFormat} />}
  {page === 'requests' && <Requests requests={requests} isManager={isManager} onDecide={decide} onCancel={cancelRequest} onRequest={() => setModal({ kind: 'request' })} timeFormat={timeFormat} />}{page === 'reports' && isManager && <Reports api={api} rooms={data.rooms || []} timeFormat={timeFormat} />}
  </>}</div></main>{modal && (modal.kind === 'user' ? <UserModal key={modal.record?._id || 'new-user'} data={data} record={modal.record} busy={saving} onClose={() => setModal(null)} onSave={save}/> : modal.kind === 'academic-view' ? <RecordDetails type={modal.type} record={modal.record} onClose={() => setModal(null)} /> : modal.kind === 'delete' ? <DeleteDialog type={modal.type} record={modal.record} busy={saving} onClose={() => setModal(null)} onDelete={deleteRecord}/> : modal.kind === 'status' ? <StatusDialog type={modal.type} record={modal.record} action={modal.action} busy={saving} onClose={() => setModal(null)} onConfirm={changeStatus}/> : <RecordModal key={modal.record?._id || `${modal.kind}-${modal.type || ''}`} modal={modal} data={data} busy={saving} onClose={() => { setModal(null); setError(''); }} onSave={save} identity={identity} />)}{logoutPrompt && <div className="modal-backdrop" role="presentation"><section className="modal delete-modal" role="alertdialog" aria-modal="true" aria-labelledby="logout-title" aria-describedby="logout-description"><div className="modal-head"><div><span className="panel-kicker">SIGN OUT</span><h2 id="logout-title">Sign out of your account?</h2></div></div><div className="delete-copy"><p id="logout-description">Are you sure you want to sign out?</p></div><div className="modal-actions"><button className="btn btn-outline" autoFocus onClick={() => setLogoutPrompt(false)}>No, stay signed in</button><button className="btn btn-primary" onClick={signOut}>Yes, sign out</button></div></section></div>}</div>;
}

function PasswordInput({ value, onChange, autoComplete = 'new-password', required, minLength, className = '' }) {
  const [visible, setVisible] = useState(false);
  const label = visible ? 'Hide password' : 'Show password';
  return <div className={`password-control ${className}`.trim()}>
    <input type={visible ? 'text' : 'password'} autoComplete={autoComplete} value={value} onChange={onChange} required={required} minLength={minLength}/>
    <button className="password-toggle" type="button" onClick={() => setVisible(current => !current)} aria-label={label} aria-pressed={visible} title={label}>{visible ? <EyeOff size={16}/> : <Eye size={16}/>}</button>
  </div>;
}

function SignIn({ onSignIn, error }) { const [identifier,setIdentifier]=useState(''); const [password,setPassword]=useState(''); return <main className="signin-page"><div className="signin-card"><div className="brand signin-brand"><span className="brand-logo-frame"><img className="brand-logo" src="/branding/aclc-college-ormoc-logo.jpg" alt=""/></span><div className="brand-copy"><strong>ACLC College</strong><small>ORMOC CITY, INC. · ROOM SCHEDULER</small></div></div><div className="eyebrow">ACLC COLLEGE OF ORMOC CITY, INC.</div><h1>Rooms that work<br/>for your day.</h1><p>Sign in to find a space, manage your schedule, or review room requests.</p>{error&&<div className="alert alert-error" role="alert">{error}</div>}<form className="modal-fields" onSubmit={e=>{e.preventDefault();onSignIn(identifier,password);}}><label>Username or Email Address<input required type="text" autoComplete="username" value={identifier} onChange={e=>setIdentifier(e.target.value)} placeholder="Enter your username or email"/></label><label>Password<PasswordInput autoComplete="current-password" required value={password} onChange={e=>setPassword(e.target.value)}/></label><button className="btn btn-primary" type="submit">Sign in <ArrowRight size={16}/></button></form><small className="signin-foot">Ormoc City Campus · No active term</small></div><div className="signin-art"><div className="art-orbit orbit-one"/><div className="art-orbit orbit-two"/><div className="art-glow"/><div className="art-caption"><span>SPACE FOR WHAT’S NEXT</span><h2>A room for every<br/>idea to take shape.</h2><p>One thoughtful campus schedule, built around the people who bring it to life.</p></div><span className="art-note"><i/> ACLC COLLEGE · EST. 2012</span></div></main> }

function Dashboard({ data, setPage, setModal, isManager, me, timeFormat }) { const today = (data.dashboard?.today || []).filter(s => !me || s.instructor?._id === me).sort((a,b) => a.startTime.localeCompare(b.startTime)); const requests = (data.requests || []).filter(r => r.status === 'Pending'); return <><div className="stat-grid"><StatCard label="Active spaces" value={data.dashboard?.activeRooms || 0} hint={`${data.dashboard?.rooms || 0} spaces in total`} icon={DoorOpen} accent="blue"/><StatCard label="Classes today" value={today.length} hint={today.length ? `${today.length} listed for today` : 'No classes scheduled today'} icon={CalendarDays} accent="mint"/><StatCard label="Active instructors" value={data.dashboard?.activeInstructors || 0} hint="Current active records" icon={Users} accent="lilac"/><StatCard label="Pending requests" value={requests.length} hint="Awaiting a scheduling decision" icon={Clock3} accent="amber" action={() => setPage('requests')}/></div><div className="dashboard-grid"><section className="panel today-panel"><div className="panel-head"><div><span className="panel-kicker">{todayLabel.toUpperCase()}</span><h2>Today on campus</h2></div><button className="text-link" onClick={() => setPage('schedules')}>Full timetable <ArrowRight size={15}/></button></div>{today.length ? <div className="timeline">{today.map((s,i) => <div className="timeline-row" key={s._id}><div className="timeline-time"><strong>{formatTime(s.startTime,timeFormat)}</strong><span>{formatTime(s.endTime,timeFormat)}</span></div><div className={`timeline-mark mark-${i%4}`}><i/></div><div className="class-card"><div><h3>{s.course?.code} <span>·</span> {s.course?.title}</h3><p>{s.instructor?.name} <span>·</span> {formatSectionDisplayName(s.section || {})}</p></div><span className="room-chip"><DoorOpen size={13}/>{s.room?.name}</span></div></div>)}</div> : <Empty icon={CalendarDays} title="No classes scheduled today" text="Classes added to the timetable will appear here." action="Explore timetable" onAction={() => setPage('schedules')}/>}</section><section className="panel utilization-panel"><div className="panel-head"><div><span className="panel-kicker">CAMPUS OVERVIEW</span><h2>Scheduling records</h2></div><button className="icon-btn" aria-label="View room list" onClick={() => setPage('rooms')}><ArrowRight size={17}/></button></div><div className="util-number">{data.dashboard?.activeRooms || 0}<small>active rooms</small></div><div className="util-legend"><span><i className="dot-blue"/> Managed spaces</span><strong>{data.dashboard?.activeInstructors || 0} <small>active instructors</small></strong></div><div className="util-tip"><span className="tip-spark">✳</span><span><strong>Schedule a class</strong><br/>View available spaces and current assignments.</span><button aria-label="Browse rooms" onClick={() => setPage('rooms')}><ArrowRight size={15}/></button></div></section></div><section className="panel upcoming-panel"><div className="panel-head"><div><span className="panel-kicker">CURRENT RECORDS</span><h2>Upcoming timetable entries</h2></div><button className="text-link" onClick={() => setPage('schedules')}>View schedule <ArrowRight size={15}/></button></div><div className="upcoming-list">{(data.dashboard?.upcoming || []).slice(0, 4).map((s,i) => <div className="upcoming-row" key={s._id}><div className={`date-tile date-${i%3}`}><small>{(s.day || '—').slice(0,3).toUpperCase()}</small><strong>{s.day?.slice(0,3) || '—'}</strong></div><div className="upcoming-main"><strong>{s.course?.code} <span>·</span> {s.course?.title}</strong><small>{s.instructor?.name} · {formatSectionDisplayName(s.section || {})}</small></div><div className="upcoming-where"><span>{s.day}</span><small>{s.room?.name} · {formatTime(s.startTime,timeFormat)}</small></div><span className="badge badge-scheduled">{s.status}</span></div>)}{!(data.dashboard?.upcoming || []).length && <Empty icon={CalendarDays} title="No timetable entries yet" text="Schedules entered by an administrator or scheduler will appear here."/>}</div></section>{isManager && requests.length > 0 && <section className="request-nudge"><span className="nudge-icon"><Clock3 size={17}/></span><span><strong>{requests.length} room {requests.length === 1 ? 'request' : 'requests'} need your attention</strong><small>Review instructor requests before their requested dates.</small></span><button className="btn btn-outline" onClick={() => setPage('requests')}>Review requests <ArrowRight size={15}/></button></section>}</> }function StatCard({ label, value, hint, icon: Icon, accent, action }) { return <button className={`stat-card accent-${accent}`} onClick={action} disabled={!action}><div className="stat-top"><span>{label}</span><span className="stat-icon"><Icon size={17}/></span></div><strong className="stat-value">{value}</strong><div className="stat-hint"><i className="hint-dot"/>{hint}</div></button> }
function Empty({ icon: Icon, title, text, action, onAction }) { return <div className="empty-inline"><span><Icon size={21}/></span><strong>{title}</strong><p>{text}</p>{action && <button className="text-link" onClick={onAction}>{action} <ArrowRight size={14}/></button>}</div> }
